var mandatoryTriggered = false;
var tempLength = 0;
tw.local.invalidTabs = [];
tw.system.coachValidation.clearValidationErrors();

/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", " Comment :" + "Shouldn't be more than 500 character");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals && tw.local.odcRequest.complianceApproval == false) {
	tw.local.odcRequest.stepLog.action = "";
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.stepLog.action", tw.resource.ValidationMessages.MandatoryFields);
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator) {
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason", 80, "Shouldn't be more than 80 characters", "Return reason :- This field shouldn't be more than 80 character");
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest) {
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.terminateReason", 80, "Shouldn't be more than 80 characters", "Termination reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {
	validateScreen();
}

function validateScreen() {
	//-------------------------------------------------Attachment----------------------------
