		if (selectedAttached.length == 0 || selectedAttached.includes(0) == false) {
			addError("tw.local.odcRequest.attachmentDetails.attachment[0].name", "Customer Request is mandatory to be checked");
		}
	}

	//-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	//debugger;
