	mandatory(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, "tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate");
	notPastDate(tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate, "tw.local.odcRequest.FinancialDetailsBR.maxCollectionDate", "cannot select date in the past", "cannot select date in the past", true);

