		mandatory(tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount, "tw.local.odcRequest.FinancialDetailsBR.chargesAndCommissionsAccount");
		mandatory(tw.local.odcRequest.FinancialDetailsBR.collectionAccount, "tw.local.odcRequest.FinancialDetailsBR.collectionAccount");
	}

	if (tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > tw.local.odcRequest.FinancialDetailsBR.documentAmount) {
		mandatory(tw.local.odcRequest.FinancialDetailsBR.amountAdvanced, "tw.local.odcRequest.FinancialDetailsBR.amountAdvanced");
		addError("tw.local.odcRequest.FinancialDetailsBR.amountAdvanced", "Amount Advanced must be less than or equal document amount");
	}
	validateTab(3, "Financial Details - Branch");
	//-----------------------------------------------FLEX CUBE COLLECTIONS VALIDATION -------------------------------------
	if (tw.local.odcRequest.FinancialDetailsBR.amountAdvanced > 0.0) {
		mandatory(tw.local.odcRequest.FcCollections.totalAllocatedAmount, "tw.local.odcRequest.FcCollections.totalAllocatedAmount");
		if (tw.local.confirmBool == false) {
 if (tw.local.odcRequest.FcCollections != null && 
 tw.local.odcRequest.FcCollections.totalAllocatedAmount != 0 && 
 tw.local.odcRequest.FcCollections.totalAllocatedAmount != tw.local.odcRequest.FinancialDetailsBR.amountAdvanced) {
 

 var userResponse = confirm("In Financial Details Tab - Total allocated amount should be equal to the advance amount");

 if (!userResponse) {
 tw.system.coachValidation.addValidationError("", "");
 } else {

 tw.local.confirmBool = true;
 }
 }
}

		if (tw.local.odcRequest.FcCollections != null && tw.local.odcRequest.FcCollections.negotiatedExchangeRate != null) {
			validateDecimal(tw.local.odcRequest.FcCollections.negotiatedExchangeRate, "tw.local.odcRequest.FcCollections.negotiatedExchangeRate", " This Field accept only 10 digits before decimal point and 6 after it", " Negotiated Exchange Rate: Shouldn't be more than 10 digits before decimal point and 6 after it");
		}

/*		if (tw.local.odcRequest.FcCollections.selectedTransactions.length > 0) {
			for (var i = 0; i < tw.local.odcRequest.FcCollections.selectedTransactions.length; i++) {
