							}
						}
						if (!found) {
							if (currentAmnt + allocatedBPM > transAmnt) {
								tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.selectedTransactions[" + i + "].amountAllocatedForCurrencyRequest", "Amount Allocated for current request must be less than or equal to transaction amount minus amount already linked in BPM");
							}
						}
