				var amountAllocatedForCurrencyRequest = tw.local.odcRequest.FcCollections.selectedTransactions[i].amountAllocatedForCurrencyRequest;
				if (!amountAllocatedForCurrencyRequest || amountAllocatedForCurrencyRequest == 0) { 
					addError("tw.local.odcRequest.FcCollections.selectedTransactions[" + i + "].amountAllocatedForCurrencyRequest", "Must be greater than 0");
				}
			}
		}

		if (tw.local.odcRequest.FcCollections.currency.value != null) {
			mandatory(tw.local.odcRequest.FcCollections.negotiatedExchangeRate, "tw.local.odcRequest.FcCollections.negotiatedExchangeRate");
		}
	}

	validateTab(4, "Flexcube collections");
	console.log(tw.system.coachValidation.validationErrors);
	

	//-----------------------------------------Financial Details - Trade FO VALIDATION ---------------------------------
	//added by maghraby
	if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment && tw.local.odcRequest.FinancialDetailsFO.discount < tw.local.oldDiscountValue) {
		alert("Discount can be amended by a higher value and not by a lower value");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.discount", "Discount can be amended by a higher value and not by a lower value");
	}

	/////////////and Discount <= Document Amount
	if (tw.local.odcRequest.FinancialDetailsFO.discount > tw.local.odcRequest.FinancialDetailsBR.documentAmount) {
		mandatory(tw.local.odcRequest.FinancialDetailsFO.discount, "tw.local.odcRequest.FinancialDetailsFO.discount");
		addError("tw.local.odcRequest.FinancialDetailsFO.discount", "Discount must be less than or equal Document Amount");
	}

	if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "001") {
		// equal sight
		integerAcceptZero(tw.local.odcRequest.FinancialDetailsFO.amountSight, "tw.local.odcRequest.FinancialDetailsFO.amountSight");
		integerAcceptZero(tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization");
		integerAcceptZero(tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization");
 }
 
 //no payment
 if (tw.local.odcRequest.BasicDetails.paymentTerms.name != "005") {
 //tw.isMandatory = mandatory(tw.local.odcRequest.FinancialDetailsFO.maturityDate, "tw.local.odcRequest.FinancialDetailsFO.maturityDate");
 //if (tw.isMandatory == true) {
		notPastDate(tw.local.odcRequest.FinancialDetailsFO.maturityDate, "tw.local.odcRequest.FinancialDetailsFO.maturityDate", "cannot select date in the past", "cannot select date in the past", true);
	//}
 }
 
	//mandatory(tw.local.odcRequest.FinancialDetailsFO.noOfDaysMaturity, "tw.local.odcRequest.FinancialDetailsFO.noOfDaysMaturity");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo, "tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo");
	mandatory(tw.local.odcRequest.FinancialDetailsFO.executionHub.name, "tw.local.odcRequest.FinancialDetailsFO.executionHub");

	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.discount, "tw.local.odcRequest.FinancialDetailsFO.discount");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.extraCharges, "tw.local.odcRequest.FinancialDetailsFO.extraCharges");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.ourCharges, "tw.local.odcRequest.FinancialDetailsFO.ourCharges");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountSight, "tw.local.odcRequest.FinancialDetailsFO.amountSight");
	//check if payment terms is free of payment 
	if(tw.local.odcRequest.BasicDetails.paymentTerms.name=="005"){
		checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.collectableAmount, "tw.local.odcRequest.FinancialDetailsFO.collectableAmount");
		//tw.local.odcRequest.ContractCreation.amount = tw.local.odcRequest.FinancialDetailsBR.documentAmount; 
	}
	else{
		if(tw.local.odcRequest.FinancialDetailsFO.collectableAmount <= 0 ){
			addError("tw.local.odcRequest.FinancialDetailsFO.collectableAmount", "This field must be greater than 0");
		}
			//tw.local.odcRequest.ContractCreation.amount = tw.local.odcRequest.FinancialDetailsFO.collectableAmount; 
	}
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization");
	checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization, "tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization");

	if (tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization > 0 && tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization > 0) {
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization", "Partial Avalization is not allowed. All the deferred amount must be in either Amount Deferred - No Aval. or Amount Deferred - Aval.");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization", "Partial Avalization is not allowed. All the deferred amount must be in either Amount Deferred - No Aval. or Amount Deferred - Aval.");
	}
	var sumAvalization = parseFloat(0);
	sumAvalization = tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization + tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization + tw.local.odcRequest.FinancialDetailsFO.amountSight;
	if (sumAvalization != tw.local.odcRequest.FinancialDetailsFO.collectableAmount) {
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefAvalization", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountDefNoAvalization", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountSight", "please ensure that the following fields is equal to Amount Collectable by NBE:Amount Sight,Amount Deferred - No Avalization,Amount Deferred - Avalization");
 }
 
//	if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate) {
//		if (tw.local.odcRequest.FinancialDetailsFO.collectableAmount > tw.local.odcRequest.oldCollectableAmount) {
//			tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.collectableAmount", "Amount Collectable by NBE AFTER change cannot be > Amount Collectable by NBE BEFORE change");
//		}
//	}
	//-------------------------MultiTenor Dates---------------------------------------------
	var sum = 0;
	var Diff = tw.local.odcRequest.FinancialDetailsFO.collectableAmount - tw.local.odcRequest.FinancialDetailsFO.amountSight;
	if (tw.local.odcRequest.BasicDetails.paymentTerms.name == "004") {
		// equal multitenor
		if (tw.local.odcRequest.FinancialDetailsFO.multiTenorDates && tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length < 2) {
			addError("tw.local.multiTenorValid", "Fill in at least two entries in Multi Tenor table");
		}
		else{

		for (var i = 0; i < tw.local.odcRequest.FinancialDetailsFO.multiTenorDates.length; i++) {

			mandatory(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].instalmentBaseDate");
			checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].instalmentTenorDays");
			mandatory(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].amount");
			mandatory(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].instalmentMaturityDate, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].instalmentMaturityDate");

			if(!!tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount){
				checkNegativeValue(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].amount");
				validateDecimal2(tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount, "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i + "].amount", "Maximum number of digits is 14", "Maximum number of digits is 14");
			}

			sum = sum + tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[i].amount;
		}
		if (tw.local.odcRequest.FinancialDetailsFO.collectableAmount != sum) {
			//tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.collectableAmount", "Sum of all Installment Amounts in a request must be equal to Amount Collectable by NBE (اجمالى المبالغ المطلوب تحصيلها)");
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.multiTenorDates["+0+"].amount", "Sum of all Installment Amounts in a request must be equal to Amount Collectable by NBE (اجمالى المبالغ المطلوب تحصيلها)");
			//tw.system.coachValidation.addValidationError("tw.local.odcRequest.FinancialDetailsFO.amountSight", "Sum of all Installment Amounts in a request must be equal to Amount Collectable by NBE (اجمالى المبالغ المطلوب تحصيلها)");
		}
		
	}
	}
	maxLength(tw.local.odcRequest.FinancialDetailsFO.referenceNo, "tw.local.odcRequest.FinancialDetailsFO.referenceNo", 16, "Shouldn't be more than 16 character", "Trade FO Reference Number:" + "Shouldn't be more than 16 character");
	maxLength(tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo, "tw.local.odcRequest.FinancialDetailsFO.financeApprovalNo", 16, "Shouldn't be more than 16 character", "Financial Approval Number:" + "Shouldn't be more than 16 character");
	
	
	var conRebate = tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt;
	var tenors = tw.local.odcRequest.FinancialDetailsFO.multiTenorDates;
	var conAmnt = tw.local.odcRequest.ContractCreation.amount;
	
	var sum = 0;
	for (var i = 0; i < tenors.length; i++) {
	 sum += tenors[i].splitRebateAmnt;
	 if (tenors[i].splitRebateAmnt > tenors[i].amount)
	 addError(
	 "tw.local.odcRequest.FinancialDetailsFO.multiTenorDates[" + i +"].splitRebateAmnt",
	 "Rebate Amount must be < or = Split Amount"
	 );
	}
	
	if ((conRebate || sum > 0) && conRebate != sum && tw.local.odcRequest.BasicDetails.paymentTerms.name == "004")
	 addError(
	 "tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt",
	 "Contract Rebate Amount must equal SUM of all Split Rebates");
	
	if (conRebate && conRebate >= conAmnt)
	 addError(
	 "tw.local.odcRequest.FinancialDetailsFO.contractRebateAmnt",
	 "Contract Rebate Amount must be < Outstanding Amount");
	
	validateTab(5, "Financial Details - Trade Fo Tab ");

	//-------------------------------------------------Importer Details VALIDATION -----------------------------------
	mandatory(tw.local.odcRequest.ImporterDetails.importerName, "tw.local.odcRequest.ImporterDetails.importerName");
	mandatory(tw.local.odcRequest.ImporterDetails.importerCountry.value, "tw.local.odcRequest.ImporterDetails.importerCountry");
	mandatory(tw.local.odcRequest.ImporterDetails.importerAddress, "tw.local.odcRequest.ImporterDetails.importerAddress");
	mandatory(tw.local.odcRequest.ImporterDetails.bank, "tw.local.odcRequest.ImporterDetails.bank");
	mandatory(tw.local.odcRequest.ImporterDetails.BICCode, "tw.local.odcRequest.ImporterDetails.BICCode");
	mandatory(tw.local.odcRequest.ImporterDetails.bankCountry.value, "tw.local.odcRequest.ImporterDetails.bankCountry");
	mandatory(tw.local.odcRequest.ImporterDetails.bankAddress, "tw.local.odcRequest.ImporterDetails.bankAddress");

	maxLength(tw.local.odcRequest.ImporterDetails.importerName, "tw.local.odcRequest.ImporterDetails.importerName", 250, "Shouldn't be more than 250 character", "Importer Name:" + "Shouldn't be more than 250 character");
	maxLength(tw.local.odcRequest.ImporterDetails.importerAddress, "tw.local.odcRequest.ImporterDetails.importerAddress", 400, "Shouldn't be more than 400 character", "Importer Detailed Address:" + "Shouldn't be more than 400 character");
	maxLength(tw.local.odcRequest.ImporterDetails.importerPhoneNo, "tw.local.odcRequest.ImporterDetails.importerPhoneNo", 20, "Shouldn't be more than 20 character", "Importer Telephone No.:" + "Shouldn't be more than 20 character");
	maxLength(tw.local.odcRequest.ImporterDetails.bank, "tw.local.odcRequest.ImporterDetails.bank", 250, "Shouldn't be more than 250 character", "Importer Bank:" + "Shouldn't be more than 250 character");
	maxLength(tw.local.odcRequest.ImporterDetails.BICCode, "tw.local.odcRequest.ImporterDetails.BICCode", 11, "Shouldn't be more than 11 character", "Importer Bank BIC Code:" + "Shouldn't be more than 11 character");
	maxLength(tw.local.odcRequest.ImporterDetails.ibanAccount, "tw.local.odcRequest.ImporterDetails.ibanAccount", 40, "Shouldn't be more than 40 character", "Importer Account(IBAN):" + "Shouldn't be more than 40 character");
	maxLength(tw.local.odcRequest.ImporterDetails.bankAddress, "tw.local.odcRequest.ImporterDetails.bankAddress", 400, "Shouldn't be more than 400 character", "Importer Bank Detailed Address:" + "Shouldn't be more than 400 character");
	maxLength(tw.local.odcRequest.ImporterDetails.bankPhoneNo, "tw.local.odcRequest.ImporterDetails.bankPhoneNo", 20, "Shouldn't be more than 20 character", "Importer Bank Telephone No.:" + "Shouldn't be more than 20 character");
	maxLength(tw.local.odcRequest.ImporterDetails.collectingBankReference, "tw.local.odcRequest.ImporterDetails.collectingBankReference", 30, "Shouldn't be more than 30 character", "Collecting Bank Reference:" + "Shouldn't be more than 30 character");
	validateTab(6, "Importer Details Tab");
	//-----------------------------------------------Shipment Details VALIDATION -------------------------------------
	mandatory(tw.local.odcRequest.ProductShipmentDetails.CBECommodityClassification.name, "tw.local.odcRequest.ProductShipmentDetails.CBECommodityClassification");
	mandatory(tw.local.odcRequest.ProductShipmentDetails.shippingDate, "tw.local.odcRequest.ProductShipmentDetails.shippingDate");
	mandatory(tw.local.odcRequest.ProductShipmentDetails.shipmentMethod.name, "tw.local.odcRequest.ProductShipmentDetails.shipmentMethod");
	mandatory( tw.local.odcRequest.ProductShipmentDetails.incoterms.name,"tw.local.odcRequest.ProductShipmentDetails.incoterms.name");
	//mandatory(tw.local.odcRequest.ProductShipmentDetails.CBEGoods.value,'tw.local.odcRequest.ProductShipmentDetails.CBEGoods');
	validateTab(7, "Product and Shipment Details Tab");
	//-------------------------------------------------Trade Fo and compliance comment validation ------------------------------
	if (tw.local.odcRequest.complianceApproval == true) mandatory(tw.local.odcRequest.tradeFoComment, "tw.local.odcRequest.tradeFoComment");
} //end of function validate

maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", "Comment: " + "Shouldn't be more than 500 character");

tw.local.errorMessage = "";
/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
 * =========================================================================================================
 *
 * Add a coach validation error
 *
 * EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
 *
 * =========================================================================================================
 */
function addError(fieldName, controlMessage, validationMessage, fromMandatory) {
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : (tw.local.errorMessage += "<li>" + validationMessage + "</li>");
}
/*
 * =================================================================================================================================
 *
 * Add a coach validation error if the string length is less than given length
 *
 * EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =================================================================================================================================
 */

function minLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field != null && field != undefined && field.length < len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * =======================================================================================================================
 *
 * Add a coach validation error if the string length is greater than given length
 *
 * EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
 *
 * =======================================================================================================================
 */
function maxLength(field, fieldName, len, controlMessage, validationMessage) {
	if (field.length > len) {
		addError(fieldName, controlMessage, validationMessage);
		return false;
	}
	return true;
}
/*
 * ==================================================================================================================
 *
 * Add a coach validation error if the field is null 'Mandatory'
 *
 * EX:	notNull(tw.local.name , 'tw.local.name')
 *
 * ==================================================================================================================
 */

function mandatory(field, fieldName) {
	if (field == null || field == undefined || field == "") {
		addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
		mandatoryTriggered = true;
		return false;
	} else {
		switch (typeof field) {
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0) {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0) {
					var msg = "Invalid Value, This field can not have a negative value.";
					addError(fieldName, msg, msg, true);
					mandatoryTriggered = true;
					return false;
				}
				break;

			default:
				// VALIDATE DATE OBJECT
				if (field && field.getTime && isFinite(field.getTime())) {
				} else {
					addError(fieldName, tw.resource.ValidationMessages.ThisFieldIsMandatory, tw.resource.ValidationMessages.MandatoryFields, true);
					mandatoryTriggered = true;
					return false;
				}
		}
	}
	return true;
}
/*
 * ==============================================================================================================================
 *
 * Add a coach validation error if the fromDate bigger than toDate
 *
 * EX:	sumDates(fomDate , toDate , 'tw.local.date' , 'this is a control validation message!' , 'this is a validation message!')
 *
 * =============================================================================================================================
 */

function sumDates(fromDate, toDate, fieldName, controlMessage, validationMessage) {
	if (toDate - fromDate == 0) {
		return true;
	}
	addError(fieldName, controlMessage, validationMessage);
	return false;
}

//=================================================================================
//edied b NAIRA
function checkNegativeValue(field, fieldName) {
	//check null values and accep zeroes
	if (field == null || field == undefined) {
		var msg = "Invalid Value, This field can not be empty.";
		addError(fieldName, msg, msg, true);
		mandatoryTriggered = true;
		return false;
	} else {
		if (field < 0) {
			var msg = "Invalid Value, This field can not be negative value.";
			addError(fieldName, msg, msg, true);
			mandatoryTriggered = true;
			return false;
		}
	}
	return true;
}
//===========================================================================================
function integerAcceptZero(field, fieldName) {
	//check integer values and accept zeroes

	if (field < 0) {
		var msg = "Invalid Value, This field can not be negative value.";
		addError(fieldName, msg, msg, true);
		return false;
	}
}
//=================================================================================
//Validate Decimal(10,6)
function validateDecimal(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,4}(\.\d{1,6})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}
//========================================================================================
function validateTab(index, tabName) {
	if (tw.system.coachValidation.validationErrors.length > tempLength) {
		if (tw.local.errorMessage.length == 0) {
			tw.local.errorMessage += "<p>" + "Please complete fields in the following tabs:" + "</p>";
		}
		tw.local.errorMessage += "<li>" + tabName + "</li>";
		tempLength = tw.system.coachValidation.validationErrors.length;
		tw.local.invalidTabs[tw.local.invalidTabs.length] = index;
	}
}
//==============================================================
//Validate Decimal(14,2)
function validateDecimal2(field, fieldName, controlMessage, validationMessage) {
	// Regular expression pattern for decimal validation
	var decimalPattern = /^\d{1,12}(\.\d{1,2})?$/;

	// Check if the decimal matches the pattern
	if (!decimalPattern.test(field)) {
		// Decimal is valid
		addError(fieldName, controlMessage, controlMessage);
		return false;
	} else {
		// Decimal is invalid
		return true;
	}
}
//=======================================================================================
tw.local.errorMessage = "";
tw.local.errorMessage != null ? (tw.local.errorPanelVIS = "EDITABLE") : (tw.local.errorPanelVIS = "NONE");

function notPastDate(date, fieldName, controlMessage, validationMessage, exclude) {
	if (exclude) {
		if (date != null && date <= new Date()) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	} else {
		var today = new Date();
		today.setHours(0, 0, 0, 0);
		if (date != null && date < today) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	}
}

function notFutureDate(date, fieldName, controlMessage, validationMessage, exclude) {
	if (exclude) {
		if (date != null && date > new Date()) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	} else {
		var today = new Date();
		today.setHours(0, 0, 0, 0);
		if (date != null && date > today) {
			addError(fieldName, controlMessage, validationMessage);
			return false;
		}
		return true;
	}
}
//=================================================================================
tw.local.errorMessage = "";

