ns16:extensionElements.ns2:postAssignmentScript:
if(tw.local.odcRequest.stepLog.action != tw.epv.CreationActions.obtainApprovals  && tw.local.odcRequest.complianceApproval == true)
{
	tw.local.odcRequest.complianceApproval = false;
}

tw.local.errorMessage = "";
tw.local.errorMSG = "";

//alert(tw.local.odcRequest.stepLog.action);

ns16:extensionElements.ns2:preAssignmentScript:
tw.local.requestAmend = tw.epv.RequestType.Amendment+"";
tw.local.requestRecreate = tw.epv.RequestType.Recreate+"";

tw.local.disable = false;

tw.local.errorMessage = "";
tw.local.errorMSG = "";

tw.local.todayDate = new Date();

ns16:scriptTask.ns16:script:
tw.local.errorMessage = "";
var mandatoryTriggered = false;
var tempLength = 0;
tw.local.invalidTabs = [];
tw.system.coachValidation.clearValidationErrors();

/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");
maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 character", " Comment :" + "Shouldn't be more than 500 character");

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals && tw.local.odcRequest.complianceApproval == false) {
	tw.local.odcRequest.stepLog.action = "";
	tw.system.coachValidation.addValidationError("tw.local.odcRequest.stepLog.action", tw.resource.ValidationMessages.MandatoryFields);
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator) {
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason", 80, "Shouldn't be more than 80 characters", "Return reason :- This field shouldn't be more than 80 character");
}

if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest) {
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.terminateReason", 80, "Shouldn't be more than 80 characters", "Termination reason :- This field shouldn't be more than 80 character");
}
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.approveRequest || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals) {
	validateScreen();
}

function validateScreen() {
	//-------------------------------------------------Attachment----------------------------
	if (tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create) {
		var selectedAttached = tw.local.odcRequest.attachmentDetails.attachment.listAllSelectedIndices;
		if (selectedAttached.length == 0 || selectedAttached.includes(0) == false) {
			addError("tw.local.odcRequest.attachmentDetails.attachment[0].name", "Customer Request is mandatory to be checked");
		}
	}

	//-------------------------------------------------BASIC DETAILS VALIDATION -----------------------------------------
	//debugger;
	mandatory(tw.local.odcRequest.BasicDetails.exportPurpose.name, "tw.local.odcRequest.BasicDetails.exportPurpose");
	mandatory(tw.local.odcRequest.BasicDetails.paymentTerms.name, "tw.local.odcRequest.BasicDetails.paymentTerms");
	mandatory(tw.local.odcRequest.BasicDetails.productCategory.name, "tw.local.odcRequest.BasicDetails.productCategory");
	mandatory(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription");
	mandatory(tw.local.odcRequest.BasicDetails.CountryOfOrigin.name, "tw.local.odcRequest.BasicDetails.CountryOfOrigin");
//	mandatory(tw.local.odcRequest.BasicDetails.operationType.value, "tw.local.odcRequest.BasicDetails.operationType");

	maxLength(tw.local.odcRequest.BasicDetails.flexCubeContractNo, "tw.local.odcRequest.BasicDetails.flexCubeContractNo", 16, tw.resource.ValidationMessages.MaxLength16, "Flex Cube Contract Number: " + tw.resource.ValidationMessages.MaxLength16);

	maxLength(tw.local.odcRequest.BasicDetails.commodityDescription, "tw.local.odcRequest.BasicDetails.commodityDescription", 160, "Shouldn't be more than 160 character", "Commodity Description: " + "Shouldn't be more than 160 character");

	if (tw.local.odcRequest.BasicDetails.Invoice.length == 0) {
		tw.local.errorMessage += "<li>" + "Fill in at least one entry in invoices" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Invoice", "Fill in at least one entry in invoices");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceDate");
			mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo");
			maxLength(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo, "tw.local.odcRequest.BasicDetails.Invoice[" + i + "].invoiceNo", 20, "Shouldn't be more than 20 character", "invoice Number: " + "Shouldn't be more than 20 character");
		}
	}
	if (tw.local.odcRequest.BasicDetails.Bills.length == 0) {
		tw.local.errorMessage += "<li>" + "Fill in at least one entry in Bills" + "</li>";
		tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Bills", "Fill in at least one entry in Bills");
	} else {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingDate, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingDate");
			mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef");
			maxLength(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef, "tw.local.odcRequest.BasicDetails.Bills[" + i + "].billOfLadingRef", 20, "Shouldn't be more than 20 character", "Bill Of lading Ref : " + "Shouldn't be more than 20 character");
		}
	}

	if (tw.local.BillExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Bills.length; i++) {
			//mandatory(tw.local.odcRequest.BasicDetails.Bills[i].billOfLadingRef , "tw.local.odcRequest.BasicDetails.Bills["+i+"].billOfLadingRef");

			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Bills", "This Bills Number already exist before for the same CIF number");
		}
	}
	if (tw.local.InvoiceExist == true) {
		for (var i = 0; i < tw.local.odcRequest.BasicDetails.Invoice.length; i++) {
			//	mandatory(tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo , "tw.local.odcRequest.BasicDetails.Invoice["+i+"].invoiceNo");
			tw.system.coachValidation.addValidationError("tw.local.odcRequest.BasicDetails.Invoice", "This Invoive Number already exist before for the same CIF number");
		}
	}

	validateTab(0, "Basic Details");
	maxLength(tw.local.odcRequest.stepLog.comment, "tw.local.odcRequest.stepLog.comment", 500, "Shouldn't be more than 500 characters", "Comment :- This field shouldn't be more than 500 character");

	//-------------------------------------------------DOCUMENT GENERATION INFO VALIDATION -----------------------------------------
	//      if (tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.NewRequest) {
	//            mandatory(tw.local.odcRequest.GeneratedDocumentInfo.customerName, "tw.local.odcRequest.GeneratedDocumentInfo.customerName");
