	////                  mandatory(tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra[0], "tw.local.odcRequest.GeneratedDocumentInfo.deliveryTermsExtra");
	////                  tw.local.errorMessage += "<li>" + "Fill in at least one entry in delivery terms Extra" + "</li>";
	//                  addError("tw.local.odcRequest.GeneratedDocumentInfo.deliveryTerms["+0+"]","Fill in at least one entry in delivery terms or delivery terms extra");
