// 
// tw.local.errorMessage += "<li>"+"Select one or more Transaction"+"</li>";	
alert("Select one or more Transaction");

tw.local.collectionCurrencyVis = "READONLY";

var selectedTransactionsIndices = [];
selectedTransactionsIndices = tw.local.odcRequest.FcCollections.retrievedTransactions.listAllSelectedIndices;

function transactionExistsInOtherTable(transaction) {

    if(!!tw.local.odcRequest.FcCollections.selectedTransactions){
   	 for (var k = 0; k < tw.local.odcRequest.FcCollections.selectedTransactions.length; k++) {
      	  if (tw.local.odcRequest.FcCollections.selectedTransactions[k].referenceNumber === transaction.referenceNumber &&
            	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getDay() == transaction.postingDate.getDay() &&
            	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getMonth() == transaction.postingDate.getMonth() &&
            	tw.local.odcRequest.FcCollections.selectedTransactions[k].postingDate.getYear() == transaction.postingDate.getYear()) {
            	return true;
        		}
    		}
    	}
    return false;
}



for (var i = 0; i < selectedTransactionsIndices.length; i++) {
    var transactionIndex = selectedTransactionsIndices[i];
    var transaction = tw.local.odcRequest.FcCollections.retrievedTransactions[transactionIndex];

    // Check if the transaction already exists in the other table
    if (!transactionExistsInOtherTable(transaction)) {
        
        transaction.requestID = tw.local.odcRequest.requestID;
        transaction.amountAllocatedForCurrencyRequest = 0;
        transaction.allocatedAmountInRequestCurrency = 0;

        // Add the transaction to selected transactions list
        tw.local.odcRequest.FcCollections.selectedTransactions.push(transaction);
    }
}

var sum = 0;
if(tw.local.odcRequest.FcCollections.selectedTransactions.length != 0)
{

	for(var i=0;i<tw.local.odcRequest.FcCollections.selectedTransactions.length;i++)
	{ 
	      tw.local.odcRequest.FcCollections.selectedTransactions[i].allocatedAmountInRequestCurrency = tw.local.odcRequest.FcCollections.selectedTransactions[i].amountAllocatedForCurrencyRequest * tw.local.odcRequest.FcCollections.negotiatedExchangeRate; 
		sum += tw.local.odcRequest.FcCollections.selectedTransactions[i].allocatedAmountInRequestCurrency;
		
	}
	tw.local.odcRequest.FcCollections.totalAllocatedAmount = sum;
}
else
   tw.local.odcRequest.FcCollections.totalAllocatedAmount = 0;

if(!tw.local.odcRequest.FcCollections.fromDate && !tw.local.odcRequest.FcCollections.ToDate)	
	if(tw.local.odcRequest.FcCollections.fromDate >= tw.local.odcRequest.FcCollections.ToDate)
	{
		tw.local.errorMessage += "<li>"+" Search Transactions From Date shouln't be greater than Search Transactions To Date"+"</li>";	
		 tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.fromDate", "Search Transactions From Date shouln't be greater than Search Transactions To Date");
		 tw.system.coachValidation.addValidationError("tw.local.odcRequest.FcCollections.ToDate", "Search Transactions From Date shouln't be greater than Search Transactions To Date");
	}

